package com.bank.locking.service;

import com.bank.locking.model.Account;
import com.bank.locking.repository.AccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.orm.ObjectOptimisticLockingFailureException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

@Slf4j
@Service
@RequiredArgsConstructor
public class AccountService {
    private final AccountRepository repo;

    // OPTIMISTIC: rare clashes, retry on version conflict
    public void debit(String id, BigDecimal amount) {
        int attempts = 0;
        while (true) {
            try {
                doDebit(id, amount);
                return;
            } catch (ObjectOptimisticLockingFailureException e) {
                if (++attempts >= 3) throw e;
                log.warning(() -> "Version conflict on " + id + ", retry " + attempts);
            }
        }
    }

    @Transactional
    protected void doDebit(String id, BigDecimal amount) {
        Account acc = repo.findById(id).orElseThrow();  // reads version
        acc.debit(amount);                               // UPDATE ... WHERE version=?
    }

    // PESSIMISTIC: hot shared row, lock up front, no retry
    @Transactional
    public void postEntry(String poolId, BigDecimal amount) {
        Account pool = repo.findByIdForUpdate(poolId).orElseThrow();  // FOR UPDATE
        pool.credit(amount);  // other txns wait for this to commit
        log.info("Posted {} to {}", amount, poolId);
    }
}
